import { collectRetreeImports, classQualifies, planClass } from "../../packages/retree-babel-plugin-compiler/bin/transform.js";
import { FUNCTION_NAMES_BIND_TO_RAW } from "../../packages/retree-core/bin/internals/proxy.js";
export default function methodCalls({ types: t }) {
    return {
        name: "retree-method-call-experiment",
        visitor: {
            Program: {
                enter(path, state) { state.calls = 0; state.imports = collectRetreeImports(path, state.opts.coreModules ?? ["@retreejs/core"]); },
                exit(path, state) {
                    if (!state.calls) return;
                    path.unshiftContainer("body", t.importDeclaration([
                        t.importSpecifier(state.prepare, t.identifier("prepareMethodCall")),
                        t.importSpecifier(state.invoke, t.identifier("invokeMethodCall")),
