                    t.isClassMethod(m) && !m.static && m.kind === "method" &&
                    !m.computed && t.isIdentifier(m.key) && !FUNCTION_NAMES_BIND_TO_RAW.has(m.key.name) && !m.decorators?.length
                ).map(m => m.key.name));
