                    if (!member.isClassMethod() || member.node.static || member.node.kind === "constructor") continue;
                    member.get("body").traverse({
                        Class(p) { p.skip(); },
                        Function(p) { if (!p.isArrowFunctionExpression()) p.skip(); },
                        CallExpression(call) {
                            const callee = call.node.callee;
                            if (!t.isMemberExpression(callee) || callee.computed ||
                                !t.isThisExpression(callee.object) || !t.isIdentifier(callee.property) ||
                                !methods.has(callee.property.name) ||
